def orbit_cost_exact(Wc, mu, nu, group_elements, action):
    best = float("inf")
    for g in group_elements:
        c = Wc(mu, action(g, nu))
        if c < best:
            best = c
    return best

from scipy.optimize import linear_sum_assignment
import numpy as np
def orbit_cost_hungarian(mu, nu):
    C = np.abs(mu[:, None] - nu[None, :])
    row, col = linear_sum_assignment(C)
    return C[row, col].sum()

import numpy as np
def orbit_cost_sorted(mu, nu):
    return np.sum(np.abs(np.sort(mu) - np.sort(nu)))
